import { useEffect, useMemo, useState } from 'react';
import { errorMessage, type MemberProfile } from '../../lib/session';
import {
  DEFAULT_SORT,
  EYEBROW,
  SEARCH_PLACEHOLDER,
  SUBTITLE,
  TITLE,
  fetchSentOffers,
  filterSentOffers,
  resultCountLabel,
  sortSentOffers,
  type SentOffer,
  type SortColumn,
  type SortDirection,
} from '../../lib/sent-offers';
import { SentOffersTable } from './SentOffersTable';
import styles from './SentOffers.module.css';

type SortState = { column: SortColumn; direction: SortDirection };

interface SentOffersProps {
  profile: MemberProfile;
  onOpenThread?: (threadId: string) => void;
}

export function SentOffers({ profile, onOpenThread }: SentOffersProps) {
  const [offers, setOffers] = useState<SentOffer[]>([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);
  const [query, setQuery] = useState('');
  const [sort, setSort] = useState<SortState>(DEFAULT_SORT);

  useEffect(() => {
    let cancelled = false;
    setLoading(true);
    setError(null);

    fetchSentOffers(profile.orgId)
      .then((data) => {
        if (!cancelled) setOffers(data);
      })
      .catch((reason: unknown) => {
        if (!cancelled) setError(errorMessage(reason));
      })
      .finally(() => {
        if (!cancelled) setLoading(false);
      });

    return () => {
      cancelled = true;
    };
  }, [profile.orgId]);

  const visibleOffers = useMemo(() => {
    const filtered = filterSentOffers(offers, query);
    return sortSentOffers(filtered, sort.column, sort.direction);
  }, [offers, query, sort.column, sort.direction]);

  const hasQuery = query.trim().length > 0;
  const openThread = onOpenThread ?? (() => {});

  const handleSort = (column: SortColumn) => {
    setSort((current) =>
      current.column === column
        ? { column, direction: current.direction === 'asc' ? 'desc' : 'asc' }
        : { column, direction: 'asc' },
    );
  };

  const handleClear = () => setQuery('');

  return (
    <div className={styles.body} data-testid="selling-body" aria-busy={loading ? 'true' : 'false'}>
      <p className={styles.eyebrow}>{EYEBROW}</p>
      <h1 className={styles.title}>{TITLE}</h1>
      <p className={styles.subtitle}>{SUBTITLE}</p>

      {error ? (
        <p role="alert" className={styles.error}>
          {error}
        </p>
      ) : !loading ? (
        <>
          <div className={styles.toolbar}>
            <div className={styles.searchWrap}>
              <input
                type="text"
                className={styles.searchInput}
                value={query}
                onChange={(event) => setQuery(event.target.value)}
                placeholder={SEARCH_PLACEHOLDER}
                aria-label={SEARCH_PLACEHOLDER}
              />
              {hasQuery && (
                <button
                  type="button"
                  className={styles.clearButton}
                  onClick={handleClear}
                  aria-label="Limpiar búsqueda"
                >
                  ×
                </button>
              )}
            </div>
            <span className={styles.resultCount} aria-live="polite">
              {resultCountLabel(visibleOffers.length)}
            </span>
          </div>
          <SentOffersTable
            offers={visibleOffers}
            sort={sort}
            onSort={handleSort}
            onOpenThread={openThread}
            hasQuery={hasQuery}
          />
        </>
      ) : null}
    </div>
  );
}

/* El sistema no expone un blanco puro; warm-cream es el neutro más cercano
   para la superficie de tarjeta/tabla. */
.outer {
  overflow: auto;
  max-height: calc(100vh - 270px);
  border: 1px solid var(--bw-line-steel);
  border-radius: 8px;
  background: var(--bw-warm-cream);
}

.table {
  width: 100%;
  border-collapse: collapse;
  font-family: var(--bw-font-body);
}

.th {
  position: sticky;
  top: 0;
  z-index: 1;
  padding: 9px 14px;
  border-bottom: 1px solid var(--bw-line-steel);
  background: var(--bw-surface-mist);
  color: var(--bw-steel-mist);
  font-size: var(--bw-size-label);
  font-weight: 600;
  text-align: left;
  text-transform: uppercase;
  letter-spacing: 0.06em;
  white-space: nowrap;
  user-select: none;
}

.sortable:hover {
  color: var(--bw-deep-steel);
}

.sortButton {
  display: inline-flex;
  align-items: center;
  gap: 4px;
  padding: 0;
  border: none;
  background: none;
  color: inherit;
  cursor: pointer;
  font: inherit;
  letter-spacing: inherit;
  text-transform: uppercase;
}

.sortButton:hover {
  color: var(--bw-deep-steel);
}

.sortIndicator {
  font-style: normal;
  font-size: var(--bw-size-hint);
  color: var(--bw-steel-mist);
  opacity: 0.3;
}

.sortAsc .sortIndicator,
.sortDesc .sortIndicator {
  color: var(--bw-calibration-blue);
  opacity: 1;
}

.td {
  padding: 10px 14px;
  border-bottom: 1px solid var(--bw-divider-mist);
  color: var(--bw-ink-steel);
  font-size: var(--bw-size-input);
  vertical-align: middle;
  white-space: nowrap;
}

.table tbody tr:last-child td {
  border-bottom: none;
}

.table tbody tr:hover td {
  background: var(--bw-row-hover-tint);
}

.ref {
  display: block;
  font-family: var(--bw-font-mono);
  font-size: var(--bw-size-input);
  font-weight: 500;
  color: var(--bw-deep-steel);
}

.brand {
  display: block;
  margin-top: 1px;
  font-family: var(--bw-font-mono);
  font-size: var(--bw-size-hint);
  color: var(--bw-input-placeholder);
}

.badge {
  display: inline-block;
  padding: 2px 7px;
  border-radius: var(--bw-radius);
  font-family: var(--bw-font-mono);
  font-size: 9px;
  letter-spacing: 0.05em;
  line-height: 1.4;
}

.badgePending {
  border: 1px solid var(--bw-badge-warning-border);
  background: var(--bw-badge-warning-bg);
  color: var(--bw-warning);
}

.badgeAccepted {
  border: 1px solid var(--bw-badge-success-border);
  background: var(--bw-badge-success-bg);
  color: var(--bw-success-dark);
}

.badgeRejected {
  border: 1px solid var(--bw-badge-danger-border);
  background: var(--bw-sensitive-bg);
  color: var(--bw-sensitive-text);
}

.badgeSuperseded {
  border: 1px solid var(--bw-badge-neutral-border);
  background: var(--bw-badge-neutral-bg);
  color: var(--bw-ink-steel-soft);
}

.action {
  height: 26px;
  padding: 0 10px;
  border-radius: 4px;
  font-family: inherit;
  font-size: var(--bw-size-label);
  font-weight: 500;
  white-space: nowrap;
  cursor: pointer;
  transition: opacity 0.12s;
}

.actionPrimary {
  border: none;
  background: var(--bw-calibration-blue);
  color: var(--bw-warm-cream);
}

.actionPrimary:hover {
  opacity: 0.87;
}

.actionGhost {
  border: 1px solid var(--bw-line-steel-strong);
  background: none;
  color: var(--bw-steel-mist);
}

.actionGhost:hover {
  border-color: var(--bw-hover-border);
  color: var(--bw-ink-steel);
}

.emptyCell {
  padding: 48px 20px;
  color: var(--bw-input-placeholder);
  font-size: var(--bw-size-body);
  text-align: center;
  white-space: normal;
}

import {
  EMPTY_NO_MATCHES,
  EMPTY_NO_OFFERS,
  rowActionLabel,
  sentAtLabel,
  type SentOffer,
  type SortColumn,
  type SortDirection,
} from '../../lib/sent-offers';
import styles from './SentOffersTable.module.css';

interface SentOffersTableProps {
  offers: SentOffer[];
  sort: { column: SortColumn; direction: SortDirection };
  onSort: (column: SortColumn) => void;
  onOpenThread: (threadId: string) => void;
  hasQuery: boolean;
}

const COLUMNS: { key?: SortColumn; label: string; sortable: boolean }[] = [
  { key: 'referencia', label: 'Referencia', sortable: true },
  { key: 'organizacion', label: 'Organización', sortable: true },
  { key: 'estado', label: 'Estado', sortable: true },
  { key: 'fecha', label: 'Fecha', sortable: true },
  { label: 'Acciones', sortable: false },
];

export function SentOffersTable({
  offers,
  sort,
  onSort,
  onOpenThread,
  hasQuery,
}: SentOffersTableProps) {
  return (
    <div className={styles.outer}>
      <table className={styles.table}>
        <thead>
          <tr>
            {COLUMNS.map((column) => {
              const sortKey = column.sortable ? column.key : undefined;
              const activeSort =
                sortKey !== undefined && sort.column === sortKey ? sort : null;

              const thClasses = [styles.th];
              if (column.sortable) thClasses.push(styles.sortable);
              if (activeSort) {
                thClasses.push(activeSort.direction === 'asc' ? styles.sortAsc : styles.sortDesc);
              }

              const ariaSort = activeSort
                ? activeSort.direction === 'asc'
                  ? 'ascending'
                  : 'descending'
                : column.sortable
                  ? 'none'
                  : undefined;

              return (
                <th key={column.label} scope="col" className={thClasses.join(' ')} aria-sort={ariaSort}>
                  {sortKey ? (
                    <button
                      type="button"
                      className={styles.sortButton}
                      onClick={() => onSort(sortKey)}
                    >
                      {column.label}
                      <span className={styles.sortIndicator} aria-hidden="true">
                        {activeSort
                          ? activeSort.direction === 'asc'
                            ? '↑'
                            : '↓'
                          : '↕'}
                      </span>
                    </button>
                  ) : (
                    column.label
                  )}
                </th>
              );
            })}
          </tr>
        </thead>
        <tbody>
          {offers.length === 0 ? (
            <tr>
              <td colSpan={COLUMNS.length} className={styles.emptyCell}>
                {hasQuery ? EMPTY_NO_MATCHES : EMPTY_NO_OFFERS}
              </td>
            </tr>
          ) : (
            offers.map((offer) => {
              let badgeClass = styles.badgeSuperseded;
              switch (offer.state) {
                case 'Pendiente':
                  badgeClass = styles.badgePending;
                  break;
                case 'Aceptada':
                  badgeClass = styles.badgeAccepted;
                  break;
                case 'Rechazada':
                  badgeClass = styles.badgeRejected;
                  break;
                default:
                  badgeClass = styles.badgeSuperseded;
                  break;
              }

              const actionClass =
                offer.state === 'Aceptada' ? styles.actionPrimary : styles.actionGhost;

              return (
                <tr key={offer.id} data-testid="sent-offer-row" data-offer-id={offer.id}>
                  <td className={styles.td}>
                    <span className={styles.ref}>{offer.partNumber}</span>
                    <span className={styles.brand}>{offer.brand}</span>
                  </td>
                  <td className={styles.td}>{offer.counterpartyName}</td>
                  <td className={styles.td}>
                    <span className={`${styles.badge} ${badgeClass}`}>{offer.state}</span>
                  </td>
                  <td className={styles.td}>{sentAtLabel(offer.createdAt)}</td>
                  <td className={styles.td}>
                    <button
                      type="button"
                      className={`${styles.action} ${actionClass}`}
                      onClick={() => onOpenThread(offer.threadId)}
                    >
                      {rowActionLabel(offer.state)}
                    </button>
                  </td>
                </tr>
              );
            })
          )}
        </tbody>
      </table>
    </div>
  );
}
